mapper.insert:
INSERT INTO memo (
    username, memo_date, source_type, market, stock_code, stock_name, title, content
)
VALUES (
    #{username}, #{memoDate}, #{sourceType}, #{market}, #{stockCode}, #{stockName}, #{title}, #{content}
)

mapper.select:
SELECT id,
       username,
       memo_date AS memoDate,
       source_type AS sourceType,
       market,
       stock_code AS stockCode,
       stock_name AS stockName,
       title,
       content,
       created_at AS createdAt,
       updated_at AS updatedAt
FROM memo
WHERE username = #{username}

    AND source_type = #{sourceType}


    AND memo_date >= #{from}


    AND memo_date <= #{to}


    AND market = #{market}


    AND stock_code = #{stockCode}


    AND (content ILIKE CONCAT('%', #{keyword}, '%')
         OR title ILIKE CONCAT('%', #{keyword}, '%')
         OR stock_name ILIKE CONCAT('%', #{keyword}, '%'))

ORDER BY COALESCE(memo_date, created_at::date) DESC, created_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, username, memo_date AS memoDate, source_type AS sourceType, market, stock_code AS stockCode, stock_name AS stockName, title, content, created_at AS createdAt, updated_at AS updatedAt FROM memo WHERE username = #{username} AND source_type = #{sourceType}
AND memo_date = #{memoDate}
AND market = #{market}
AND stock_code = #{stockCode}
AND stock_code IS NULL
ORDER BY created_at DESC, id DESC

mapper.update:
UPDATE memo
SET title = #{title},
    content = #{content},
    updated_at = NOW()
WHERE id = #{id}
  AND username = #{username}

mapper.delete:
DELETE FROM memo
WHERE id = #{id}
  AND username = #{username}
